(() => {
  'use strict';
  const db=window.RESEARCH_DB,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const typeNames={all:'全部',topic:'选题建议',contest:'竞赛信息',case:'获奖案例',resource:'研究素材',guide:'研究指南',major:'专业索引'};
  const tiers=Object.fromEntries(db.difficultyLevels.map(t=>[t.id,t])),byId=new Map(db.records.map(r=>[r.id,r])),engine=ResearchSearch.create(db),params=new URLSearchParams(location.search);
  const defaults={q:'',type:'all',group:'all',major:'all',level:'all',difficulty:'all',sort:'relevance',scope:'all',mode:'all',page:1},state={...defaults};
  for(const k of Object.keys(defaults))if(k!=='page'&&params.has(k))state[k]=params.get(k);
  const options={type:Object.keys(typeNames),group:['all',...db.groups.map(g=>g.id)],major:['all',...db.majors.map(m=>m.id)],level:['all','入门','进阶','导师协作'],difficulty:['all',...Object.keys(tiers)],sort:['relevance','difficulty','date','title'],scope:['all','title','body','sources'],mode:['all','any','phrase']};
  for(const [k,values] of Object.entries(options))if(!values.includes(state[k]))state[k]=defaults[k];
  if(state.difficulty!=='all')state.type='topic';
  if(state.major!=='all'&&state.group!=='all'&&db.majors.find(m=>m.id===state.major).group!==state.group)state.group='all';
  let lastFocus=null,debounce;const trail=[];
  function url(){const p=new URLSearchParams;for(const [k,v] of Object.entries(state))if(k!=='page'&&v!==defaults[k])p.set(k,v);history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash);}
  function highlight(text,terms){const pieces=String(text).split(/(risc[\s_-]*v)/i),variants=[...new Set(terms)].filter(v=>v!=='riscv').sort((a,b)=>b.length-a.length);const pattern=variants.map(v=>v.replace(/[.*+?^$(){}|[\]\\]/g,'\\$&')).join('|'),re=pattern?new RegExp(pattern,'gi'):null;return pieces.map((p,i)=>{if(i%2)return terms.includes('riscv')?'<mark>'+esc(p)+'</mark>':esc(p);if(!re)return esc(p);let out='',last=0;for(const m of p.matchAll(re)){if(/^[a-z0-9]{1,3}$/i.test(m[0])&&(/[a-z0-9_]/i.test(p[m.index-1]||'')||/[a-z0-9_]/i.test(p[m.index+m[0].length]||'')))continue;out+=esc(p.slice(last,m.index))+'<mark>'+esc(m[0])+'</mark>';last=m.index+m[0].length;}return out+esc(p.slice(last));}).join('');}
  function excerpt(hit){const start=Math.max(0,hit.position-45),end=Math.min(hit.text.length,start+185);return (start?'…':'')+highlight(hit.text.slice(start,end),hit.terms)+(end<hit.text.length?'…':'');}
  function snippets(item){const candidates=item.hits.filter(h=>!['title','summary','tags','major'].includes(h.field)&&h.text.length>20&&!h.text.includes(item.r.title));if(!candidates.length)return '';const ranks={body:5,difficulty:4,report:3,sources:2,bridge:1};candidates.sort((a,b)=>ranks[b.field]-ranks[a.field]||b.terms.length-a.terms.length);const selected=[candidates[0]];if(item.totalTerms>1){const other=candidates.find(h=>h!==selected[0]&&h.terms.some(t=>!selected[0].terms.includes(t)));if(other)selected.push(other);}return selected.map(h=>'<p><b>'+esc(h.label)+'：</b>'+excerpt(h)+'</p>').join('');}
  function card(item){const {r,hits}=item,tier=tiers[r.difficulty],ss=r.sourceIds.map(id=>db.sources[id]),terms=[...new Set(hits.flatMap(h=>h.terms))];return '<article class="card"><div class="card-top"><span class="type-badge type-'+r.type+'">'+typeNames[r.type]+'</span>'+(tier?'<span class="difficulty-badge '+tier.id.toLowerCase()+'">'+tier.id+' · '+esc(tier.name)+'</span>':'')+'<span class="stage">'+esc(r.level?'准备：'+r.level:r.status||'公开资料')+'</span></div><h3><button class="title-button" data-detail="'+r.id+'">'+highlight(r.title,terms)+'</button></h3><p class="card-summary">'+highlight(r.summary,terms)+'</p>'+(hits.length?'<div class="match"><span>命中 '+[...new Set(hits.map(h=>h.label))].slice(0,4).join(' / ')+(item.totalTerms>1?' · '+item.matchedTerms+'/'+item.totalTerms+' 个词':'')+'</span>'+snippets(item)+'</div>':'')+'<div class="card-bottom"><span>'+esc((r.tags||[]).slice(0,3).join(' · '))+'</span><span title="'+esc(ss.map(s=>s.org).join(' · '))+'">来源：'+esc(ss[0]?.org||'')+(ss.length>1?' +'+(ss.length-1):'')+'</span></div></article>';}
  function render(){const list=engine.search(state),size=10,pages=Math.max(1,Math.ceil(list.length/size));state.page=Math.min(state.page,pages);
    $('#type-nav').innerHTML=Object.entries(typeNames).filter(([id])=>id!=='major'||state.type==='major').map(([id,name])=>'<button class="nav-button '+(state.type===id?'active':'')+'" data-type="'+id+'" aria-pressed="'+(state.type===id)+'">'+name+'<span>'+db.records.filter(r=>id==='all'||r.type===id).length+'</span></button>').join('');
    $('#major-select').innerHTML='<option value="all">所有专业</option>'+db.groups.filter(g=>state.group==='all'||state.group===g.id).map(g=>'<optgroup label="'+esc(g.name)+'">'+db.majors.filter(m=>m.group===g.id).map(m=>'<option value="'+m.id+'">'+esc(m.name)+'</option>').join('')+'</optgroup>').join('');
    for(const k of ['major','difficulty','sort','scope','mode','group','level'])$('#'+k+'-select').value=state[k];
    if($('#search-input').value.trim()!==state.q)$('#search-input').value=state.q;
    $('#advanced-summary').textContent=({all:'全文',title:'仅标题',body:'方案与报告',sources:'来源'})[state.scope]+' · '+({all:'同时匹配',any:'任一词',phrase:'完整短语'})[state.mode]+(state.group!=='all'||state.level!=='all'?' · 有附加筛选':'');
    $('#result-title').firstChild.textContent=state.q?'搜索结果 ':typeNames[state.type]+'资料 ';$('#result-count').textContent=list.length+' 条';
    $('#result-description').textContent=state.q?({relevance:'按标题、摘要与正文匹配程度排序',date:'按核验日期排序',title:'按标题名称排序',difficulty:'按项目难度排序'})[state.sort]+'；高亮实际命中词。':state.difficulty!=='all'?'难度筛选仅显示选题；点标题查看最小版本、素材和协作路线。':'点标题查看详细方案与原始来源。';
    $('#cards').innerHTML=list.length?list.slice((state.page-1)*size,state.page*size).map(card).join(''):'<div class="empty"><h3>没有找到匹配资料</h3><p>可放宽专业或难度，在精细检索中切换“匹配任一词”，或使用文献检索式到外部搜索。</p></div>';
    $('#pagination').innerHTML=list.length>size?'<button class="page-button" data-page="-1" '+(state.page===1?'disabled':'')+'>← 上一页</button><span>'+state.page+' / '+pages+' 页</span><button class="page-button" data-page="1" '+(state.page===pages?'disabled':'')+'>下一页 →</button>':'';
    $('#web-search').href='https://www.bing.com/search?q='+encodeURIComponent((state.q||'毕业设计 竞赛')+' '+(state.major==='all'?'佛山大学':db.majors.find(m=>m.id===state.major).name));url();
  }
  function reset(){clearTimeout(debounce);Object.assign(state,defaults);$('#advanced-search').open=false;render();}
  function linked(ids){return '<div class="related-topics">'+ids.map(id=>byId.get(id)).filter(Boolean).map(r=>'<button class="related-topic" data-detail="'+r.id+'">'+esc(r.title)+' ↗</button>').join('')+'</div>';}
  function bridge(r){const b=r.researchBridge;if(!b)return '';return '<section class="research-bridge"><h3>以赛带学 · 从素材到项目</h3><p class="assessment-note">以下为拟议准备路线，需团队与导师确认；关联不代表已满足报名资格。</p><h4>候选竞赛</h4><p>'+esc(b.contestNote)+'</p>'+linked(b.contestIds)+'<h4>获奖选题怎么借鉴</h4><p>'+esc(b.caseNote)+'</p>'+linked(b.caseIds)+'<h4>可直接查阅的研究素材</h4>'+linked(b.resourceIds)+'<h4>建议跨专业分工</h4><div class="role-grid">'+b.roles.map(v=>'<div><strong>'+v.majorIds.map(id=>esc(db.majors.find(m=>m.id===id).name)).join(' / ')+'</strong><p>'+esc(v.role)+'</p><small>交付：'+esc(v.deliverable)+'</small></div>').join('')+'</div><h4>两周预研交付</h4><ol>'+b.milestones.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ol><h4>拿去和导师讨论的问题</h4><ul>'+b.mentorQuestions.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul><h4>文献与图书馆检索式</h4><div class="library-queries">'+b.librarySearch.map(v=>'<div><code>'+esc(v)+'</code><a href="https://www.bing.com/search?q='+encodeURIComponent(v)+'" target="_blank" rel="noopener noreferrer" aria-label="外部搜索 '+esc(v)+'">搜索 ↗</a></div>').join('')+'</div><p class="assessment-note">以上是建议检索式；图书馆数据库的全文权限与校内访问条件需核对。记录文献版本、DOI、样本与对照方法。</p></section>';}
  function rubric(){return `<section class="rubric"><h3>四个维度的分层标准</h3><p>${esc(db.difficultyMethod.rule)}</p><div class="rubric-scroll" tabindex="0" role="region" aria-label="难度维度对照表"><table><caption>每项按 1–4 级评估，取最高项作为项目难度</caption><thead><tr><th scope="col">维度</th>${db.difficultyLevels.map(t=>`<th scope="col">${t.id}<br>${esc(t.name)}</th>`).join('')}</tr></thead><tbody>${db.difficultyDimensions.map(d=>`<tr><th scope="row">${esc(d.name)}</th>${d.criteria.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="assessment-note">评估版本 ${esc(db.difficultyMethod.version)} · ${esc(db.difficultyMethod.assessed)}。${esc(db.difficultyMethod.note)}</p></section>`}
  function difficultyView(r){if(!r.difficultyProfile)return '';const p=r.difficultyProfile,t=tiers[r.difficulty];return `<section class="difficulty-profile" aria-label="选题难度档案"><div class="profile-heading"><span class="difficulty-badge ${t.id.toLowerCase()}">${t.id} · ${esc(t.name)}</span><span>按当前拟议范围评估</span></div><p class="difficulty-reason"><strong>主要瓶颈：</strong>${esc(p.reason)}</p><div class="dimension-grid">${db.difficultyDimensions.map(d=>`<div class="dimension-card"><div><strong>${esc(d.name)}</strong><b>${p.dimensions[d.id]}<small> / 4</small></b></div><p>${esc(d.criteria[p.dimensions[d.id]-1])}</p></div>`).join('')}</div><h3>先修知识</h3><ul>${p.prerequisites.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><h3>资源条件</h3><ul>${p.resources.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><div class="scope-box"><strong>先做这个最小版本</strong><p>${esc(p.minimum)}</p><strong>再考虑扩展</strong><p>${esc(p.stretch)}</p></div><p class="effort-detail"><strong>规划投入：</strong>${esc(p.effort)}。<br><strong>建议协作：</strong>${esc(p.team)}。</p><p class="assessment-note">调研评估，非学校评级。投入估计以具备先修基础为前提；增加范围或缺少数据、设备时需重新评估。</p><button class="text-button" data-help>查看分层标准与学习路线 ↗</button></section>`}
  function related(r){const items=(r.relatedTopicIds||[]).map(id=>db.records.find(v=>v.id===id));return items.length?`<section><h3>相关起步与延伸方向</h3><div class="related-topics">${items.map(v=>`<button class="related-topic" data-detail="${v.id}"><span class="difficulty-badge ${v.difficulty.toLowerCase()}">${v.difficulty}</span>${esc(v.title)} ↗</button>`).join('')}</div></section>`:''}
  function source(s){return `<div class="source-box"><strong>${esc(s.title)}</strong><div class="source-meta">${esc(s.org)} · ${esc(s.kind)} · 核验 ${esc(s.checked)}</div><a class="source-url" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.url)} ↗</a>${s.access?`<div class="source-status">${esc(s.access)}</div>`:''}<div class="source-action"><span>${esc(s.note||'请以原始页面及最新通知为准')}</span><button class="copy-button" data-copy="${esc(s.url)}">复制网址</button></div></div>`}
  function display(r){$('#detail-kicker').textContent=typeNames[r.type]+' / '+r.id.toUpperCase();$('#detail-content').innerHTML=`<h2 id="detail-title">${esc(r.title)}</h2><p class="lead">${esc(r.summary)}</p><div class="tags">${(r.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${r.type==='topic'?'<div class="fact-note">调研建议 · 非学校官方毕设题目。下面的方案和周期是拟议研究路线；来源支持背景、工具或数据，不代表原作者或学院认可本题。性能目标需要实际实验验证。</div>':''}${r.type==='major'?'<div class="fact-note">公开专业栏目索引，页面未明确专业列表对应年份；不作为 2026 年完整招生计划、培养方案或学院现状的证明。</div>':''}${bridge(r)}${difficultyView(r)}${r.id==='guide-difficulty'?rubric():''}${r.sections.map(s=>`<section><h3>${esc(s.heading)}</h3>${s.items.length===1?`<p>${esc(s.items[0])}</p>`:`<ul>${s.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}</section>`).join('')}${related(r)}${r.report?`<h3>完整调研材料</h3><div class="dialog-links"><a href="downloads/ic-research.md" download>下载 Markdown 版 ↓</a></div><pre class="report-text">${esc(db.report)}</pre>`:''}<section><h3>${r.type==='topic'?'背景、工具与数据依据':'原始来源'} · ${r.sourceIds.length} 个</h3>${r.sourceIds.map(id=>source(db.sources[id])).join('')}</section><div class="source-meta" style="margin-top:20px">资料整理 ${esc(r.date)} · 可搜索标题、正文、标签、专业、难度、先修知识和来源</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;}

  function show(r,back=false){if(!r)return;if(!$('#detail-dialog').open){lastFocus=document.activeElement;trail.length=0;}if(!back&&trail.at(-1)?.id!==r.id)trail.push(r);display(r);$('#detail-back').hidden=trail.length<2;}
  $('#detail-back').addEventListener('click',()=>{trail.pop();show(trail.at(-1),true);});
  function about(){show({id:'about',type:'guide',title:'资料范围与搜索说明',summary:'把竞赛、获奖题目、毕设素材和跨专业协作放在一个资料库中。',tags:[],date:db.date,sourceIds:['fosu-catalog','fosu-charter'],sections:[{heading:'内容与来源',items:[db.majors.length+' 个公开专业栏目；'+db.records.filter(r=>r.type==='topic').length+' 个拟议选题；'+Object.keys(db.sources).length+' 个来源。专业栏目页面未注明适用年份，不代表现行完整招生目录。','案例事实以主办方或高校页面为依据；题目、路线、难度和协作分工是资料库建议。公示题名不等于论文全文，历史赛季不等于当前可报名。']},{heading:'搜索规则',items:['默认全文同时匹配所有词。精细检索可改为任一词或完整短语，并限定标题、详细方案与报告、来源机构与网址。双引号内保留短语；其他词支持常见缩写。','标题、标签和摘要权重较高，正文、先修条件、跨专业分工、来源和集成电路完整报告均可命中。每条结果显示实际命中的字段和片段。按词匹配，不自动理解问题或生成搜索答案。','例：RISC-V 验证；牛 跨个体；排程 CP-SAT；量化 延迟；来源范围内搜索大学名称。选题难度只对选题适用，切换其他资料类型会清除难度条件。']},{heading:'怎样组织研究',items:['先查看候选竞赛规则和真实案例，再看选题的最小版本、数据工具、分工和两周预研交付；把待确认问题带给导师。不同专业可以共用验证和资料方法，不能强行套用同一种题目。','当前是 '+db.date+' 的整理快照，未自动抓取实时网页。站内搜索本地完成；打开来源或 Bing 搜索会访问外部网站。来源仍可能变更或需要登录。','服务默认只监听本机。GitHub 开源仓库可供他人下载运行；公网访问需要另行部署。']}]});}
  $('#edition-date').textContent=db.date;$('#corpus-count').textContent=db.records.length+' 条资料 · '+db.majors.length+' 个专业栏目 · '+Object.keys(db.sources).length+' 个来源';
  $('#group-select').innerHTML='<option value="all">所有领域</option>'+db.groups.map(g=>'<option value="'+g.id+'">'+esc(g.name)+'</option>').join('');
  if(state.scope!=='all'||state.mode!=='all'||state.group!=='all'||state.level!=='all')$('#advanced-search').open=true;
  $('#search-form').addEventListener('submit',e=>{e.preventDefault();clearTimeout(debounce);state.q=$('#search-input').value.trim();state.page=1;render();});
  $('#search-input').addEventListener('input',()=>{clearTimeout(debounce);debounce=setTimeout(()=>{state.q=$('#search-input').value.trim();state.page=1;render();},220);});
  for(const key of ['major','difficulty','sort','scope','mode','group','level'])$('#'+key+'-select').addEventListener('change',e=>{state.q=$('#search-input').value.trim();clearTimeout(debounce);state[key]=e.target.value;if(key==='difficulty'&&state.difficulty!=='all')state.type='topic';if(key==='group')state.major='all';state.page=1;render();});
  $('#difficulty-help').addEventListener('click',()=>show(byId.get('guide-difficulty')));$('#reset').addEventListener('click',reset);$('#about-button').addEventListener('click',about);
  $('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
  $('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
  document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.type){clearTimeout(debounce);state.q=$('#search-input').value.trim();state.type=t.dataset.type;if(state.type!=='topic')state.difficulty='all';state.page=1;render();}if(t.dataset.detail){if(!$('#detail-dialog').open)lastFocus=t;show(byId.get(t.dataset.detail));}if(t.hasAttribute('data-help'))show(byId.get('guide-difficulty'));if(t.dataset.page){state.page+=Number(t.dataset.page);render();$('#results').scrollIntoView({behavior:'smooth',block:'start'});}if(t.dataset.copy){try{await navigator.clipboard.writeText(t.dataset.copy);$('#toast').textContent='已复制来源网址';}catch{$('#toast').textContent='请选中网址手动复制';}$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,2200);}});
  render();
})();
